  const MARKS = [['.', 'पूर्णविराम'], [',', 'स्वल्पविराम'], [';', 'अर्धविराम'], [':', 'अपूर्णविराम'], ['?', 'प्रश्नचिन्ह'], ['!', 'उद्गारचिन्ह'], ['-', 'संयोगचिन्ह'], ['—', 'अपसारणचिन्ह'], ['‘ ’', 'एकेरी अवतरणचिन्ह'], ['“ ”', 'दुहेरी अवतरणचिन्ह']];
