  def('m7mrSyn', 'समानार्थी शब्द, वेगळ्या अर्थाचा शब्द', (R, Lv) => {
    const all = [...S.LANG7_B.SYN7, ...B4.SYN], pool = Lv === 1 ? all : S.LANG7_B.SYN7;
    if (vt(R, Lv, [1, 2]) === 2) {
      const big = all.filter(x => x[1].length >= 2), i = R.ri(0, big.length - 1), g = [big[i][0], ...big[i][1]], three = pickN(R, g, 3);
      const cand = big.filter((x, j) => j !== i && !x[1].some(y => g.includes(y)) && !g.includes(x[0])); if (!cand.length) return null; const oth = R.pick(cand), odd = R.pick(oth[1]);
      return mk(R, { q: 'पुढीलपैकी वेगळ्या अर्थाचा शब्द असलेला पर्याय निवडा.', a: odd, w: three, steps: [`${three.join(', ')} — सर्वांचा अर्थ "${g[0]}"`, `${odd} = ${oth[0]}`] });
    }
    const i = R.ri(0, pool.length - 1), [w, ss] = pool[i], a = R.pick(ss), wr = pool.filter((_, j) => j !== i).map(x => R.pick(x[1]));
    return mk(R, { q: `${Q(w)} या शब्दाचा समानार्थी शब्द कोणता?`, a, w: R.shuffle(wr), steps: [`${w} = ${ss.join(', ')}`] });
  });
