    if (Lv === 3 && R.r() < 0.4) { const ok = pickN(R, pool, 3).map(p => `${p[0]} × ${p[1]}`), s = R.pick(S.LANG7_B.SYN7), bad = `${s[0]} × ${s[1][0]}`;
      return mk(R, { q: 'विरुद्धार्थी शब्दांची चुकीची जोडी ओळखा.', a: bad, w: ok, steps: [`${s[0]} आणि ${s[1][0]} हे समानार्थी आहेत, विरुद्धार्थी नाहीत`] }); }
    return mk(R, { q: `${Q(w)} या शब्दाचा विरुद्धार्थी शब्द कोणता?`, a, w: R.shuffle(pool.filter((_, j) => j !== i).map(p => rev ? p[0] : p[1])), steps: [`${w} × ${a}`] });
